"""Emit the compact model-by-arm summary table from eval_tables.py JSON files.

Usage: python3 eval_summary.py tables/opus.json tables/sol.json --out tables/summary.tex

One block of three rows per model: mean cost per cell, the hybrid/agent-only
cost ratio with its 95% bootstrap interval, cells failed at the first attempt,
complete cells over scored cells (asterisk: scoring in progress),
mean input/output tokens, and Edit, verify, and WP calls summed over the arm.
"""

import argparse
import json
from pathlib import Path

ARMS = (("agent_only", "agent-only"), ("hybrid_guided", "hybrid-guided"), ("hybrid_flexible", "hybrid-flexible"))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("summaries", type=Path, nargs="+")
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--label", action="append", default=[], metavar="MODEL=LABEL",
                        help="override the row label for a model, e.g. to mark placeholder data")
    args = parser.parse_args()
    overrides = dict(item.split("=", 1) for item in args.label)
    lines = [
        r"\begin{tabular}{llrlrrrrrr}",
        r"\toprule",
        r"model & arm & cost & vs. agent [95\% CI] & failed & complete & I/O k & edits & verifies & \WP \\",
        r"\midrule",
    ]
    for n, path in enumerate(args.summaries):
        d = json.loads(path.read_text())
        labels = {"claude-opus-5": "Opus~5", "gpt-5.6-sol": "Sol~5.6", "gpt-5.6-terra": "Terra~5.6", "glm-5.3[1m]": "GLM~5.3"}
        label = overrides.get(d["model"], labels[d["model"]])
        if n:
            lines.append(r"\midrule")
        for arm, name in ARMS:
            a = d["arms"][arm]
            ratio = a.get("ratio_vs_agent")
            vs = "---" if ratio is None else f"{ratio['estimate']:.2f} [{ratio['ci95'][0]:.2f}, {ratio['ci95'][1]:.2f}]"
            complete = "---" if not a["scored"] else f"{a['complete']}/{a['scored']}" + (r"$^\ast$" if a["pending"] else "")
            lines.append(
                f"{label if arm == 'agent_only' else ''} & {name} & \\${a['mean_cost']:.3f} & {vs} & {a['first_attempt_failures']} & {complete} & "
                f"{a['mean_input_k']:.0f}/{a['mean_output_k']:.1f} & {a['edits']} & {a['verifies']} & {a['wp_calls']} \\\\"
            )
    lines += [r"\bottomrule", r"\end{tabular}"]
    args.out.write_text("% Generated by eval_summary.py; do not edit.\n" + "\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
